import{_ as c,c as t,o as e,ak as s}from"./chunks/framework.gmyagHYt.js";const g=JSON.parse('{"title":"安装","description":"使用msi安装程序自动完成安装","frontmatter":{"title":"安装","description":"使用msi安装程序自动完成安装","layout":"doc"},"headers":[],"relativePath":"version/v3/docs/base/install.md","filePath":"version/v3/docs/base/install.md"}'),l={name:"version/v3/docs/base/install.md"};function o(n,a,d,i,r,p){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="_1-安装" tabindex="-1">1.安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to “1.安装”">​</a></h1><ul><li><h2 id="_1-1-已完成准备工作" tabindex="-1">1.1 已完成准备工作 <a class="header-anchor" href="#_1-1-已完成准备工作" aria-label="Permalink to “1.1 已完成准备工作”">​</a></h2><p>双击运行刚才下载的安装程序，可能会出现<code>Windows defender</code>的提示，直接点击<code>更多信息</code>，展开之后选择<code>仍要运行</code>即可。 <img src="https://tuchuang.ets2la.cn/25-12/20250721084016.png" alt="" loading="lazy"><br> 然后会进入到安装向导，点击 <code>下一步</code> 即可<br><img src="https://tuchuang.ets2la.cn/csharp/20260902103726262.png" alt="" loading="lazy"> 勾选 <code>我接受许可协议中的条款</code> 并点击 <code>下一步</code><img src="https://tuchuang.ets2la.cn/csharp/20260902103806945.png" alt="" loading="lazy"> 点击 <code>安装</code> 来安装软件 <img src="https://tuchuang.ets2la.cn/csharp/20260902103839288.png" alt="" loading="lazy"> 这一步请慢慢等待 应该很快会安装成功 <img src="https://tuchuang.ets2la.cn/csharp/20260902103855166.png" alt="" loading="lazy"> 安装完成后默认勾选 <code>启动ETS2LA</code> ，然后点击 <code>完成</code><img src="https://tuchuang.ets2la.cn/csharp/20260902104009805.png" alt="" loading="lazy"></p></li><li><h2 id="_1-2-未完成准备工作" tabindex="-1">1.2 未完成准备工作 <a class="header-anchor" href="#_1-2-未完成准备工作" aria-label="Permalink to “1.2 未完成准备工作”">​</a></h2><p>双击安装程序之后可能会出现会<code>Windows defender</code>的提示，直接点击<code>更多信息</code>，展开之后选择<code>仍要运行</code>即可。 <img src="https://tuchuang.ets2la.cn/25-12/20250721084016.png" alt="" loading="lazy"><br> 弹出 <code>需要其他组件</code> 的提示框，选择安装程序会自动下载并安装.NET10（如果期间弹出UAC则手动允许即可）。 <img src="https://tuchuang.ets2la.cn/csharp/20260902103333221.png" alt="" loading="lazy"> 然后会进入到安装向导，点击 <code>下一步</code> 即可<br><img src="https://tuchuang.ets2la.cn/csharp/20260902103726262.png" alt="" loading="lazy"> 勾选 <code>我接受许可协议中的条款</code> 并点击 <code>下一步</code><img src="https://tuchuang.ets2la.cn/csharp/20260902103806945.png" alt="" loading="lazy"> 点击 <code>安装</code> 来安装软件 <img src="https://tuchuang.ets2la.cn/csharp/20260902103839288.png" alt="" loading="lazy"> 这一步请慢慢等待 应该很快会安装成功 <img src="https://tuchuang.ets2la.cn/csharp/20260902103855166.png" alt="" loading="lazy"> 安装完成后默认勾选 <code>启动ETS2LA</code> ，然后点击 <code>完成</code><img src="https://tuchuang.ets2la.cn/csharp/20260902104009805.png" alt="" loading="lazy"></p></li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>目前对于A卡可能会无法渲染路径线的问题 这不是你的问题 需耐心等待作者修复即可</p></div>',3)])])}const u=c(l,[["render",o]]);export{g as __pageData,u as default};
